patches.diff:
From d4c92ea0b0c0fb579bdd3dd2b9e4dd00413179c1 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 19:16:48 +0100
Subject: [PATCH] applets/pager: add an option to scroll column by column

Scrolling over the pager always followed the desktop numbers, going
through a whole row before the next one. A new "Scroll column by column"
option makes the wheel go down each column of the grid first instead.

BUG: 525164
---
 applets/pager/main.xml              |  4 ++++
 applets/pager/qml/configGeneral.qml |  6 ++++++
 applets/pager/qml/main.qml          | 24 ++++++++++++++++++------
 3 files changed, 28 insertions(+), 6 deletions(-)

diff --git a/applets/pager/main.xml b/applets/pager/main.xml
index d47b935b1e..e7f755f2ce 100644
--- a/applets/pager/main.xml
+++ b/applets/pager/main.xml
@@ -31,6 +31,10 @@
         <label>Whether to wrap page when navigating with pager</label>
         <default>false</default>
     </entry>
+    <entry name="scrollByColumn" type="Bool">
+        <label>Whether scrolling over the pager goes through each column before moving to the next one</label>
+        <default>false</default>
+    </entry>
     <entry name="currentDesktopSelected" type="Enum">
         <label>What to do on left-mouse click on a desktop rectangle.</label>
         <choices>
diff --git a/applets/pager/qml/configGeneral.qml b/applets/pager/qml/configGeneral.qml
index 23074d9ab6..07231b9053 100644
--- a/applets/pager/qml/configGeneral.qml
+++ b/applets/pager/qml/configGeneral.qml
@@ -23,6 +23,7 @@ KCM.SimpleKCM {
     property alias cfg_pagerLayout: pagerLayout.currentIndex
     property alias cfg_showOnlyCurrentScreen: showOnlyCurrentScreen.checked
     property alias cfg_wrapPage: wrapPage.checked
+    property alias cfg_scrollByColumn: scrollByColumn.checked

     Kirigami.FormLayout {
         QQC2.ButtonGroup {
@@ -57,6 +58,11 @@ KCM.SimpleKCM {
             text: i18nc("@option:check", "Navigation wraps around")
         }

+        QQC2.CheckBox {
+            id: scrollByColumn
+            text: i18nc("@option:check", "Scroll column by column")
+        }
+

         Item {
             Kirigami.FormData.isSection: true
diff --git a/applets/pager/qml/main.qml b/applets/pager/qml/main.qml
index b4211ddbbd..d93ba4a969 100644
--- a/applets/pager/qml/main.qml
+++ b/applets/pager/qml/main.qml
@@ -114,19 +114,31 @@ PlasmoidItem {
                 increment--;
             }

+            let order = [...Array(repeater.count).keys()];
+            if (Plasmoid.configuration.scrollByColumn) {
+                const columns = pagerItemGrid.columns;
+                order = [];
+                for (let column = 0; column < columns; ++column) {
+                    for (let page = column; page < repeater.count; page += columns) {
+                        order.push(page);
+                    }
+                }
+            }
+
             while (increment !== 0) {
+                const position = order.indexOf(pagerModel.currentPage);
                 if (increment < 0) {
-                    const nextPage = Plasmoid.configuration.wrapPage?
-                        (pagerModel.currentPage + 1) % repeater.count :
-                        Math.min(pagerModel.currentPage + 1, repeater.count - 1);
+                    const nextPage = order[Plasmoid.configuration.wrapPage ?
+                        (position + 1) % order.length :
+                        Math.min(position + 1, order.length - 1)];
                     // At the last desktop: changePage() on the current one would toggle Show Desktop
                     if (nextPage !== pagerModel.currentPage) {
                         pagerModel.changePage(nextPage);
                     }
                 } else {
-                    const previousPage = Plasmoid.configuration.wrapPage ?
-                        (repeater.count + pagerModel.currentPage - 1) % repeater.count :
-                        Math.max(pagerModel.currentPage - 1, 0);
+                    const previousPage = order[Plasmoid.configuration.wrapPage ?
+                        (order.length + position - 1) % order.length :
+                        Math.max(position - 1, 0)];
                     if (previousPage !== pagerModel.currentPage) {
                         pagerModel.changePage(previousPage);
                     }
-- 
2.53.0
